'use client';

import { useNow } from '@/registry/ndeko/hooks/use-agent-run';

import { OFFER_LENGTH_MS } from './data';

const SECOND_MS = 1000;
const MINUTE_MS = 60 * SECOND_MS;
const HOUR_MS = 60 * MINUTE_MS;
const DAY_MS = 24 * HOUR_MS;

const LOADED_AT = Date.now();

const ENDS_AT = LOADED_AT + OFFER_LENGTH_MS;

function twoDigits(value: number) {
  return String(value).padStart(2, '0');
}

function clockTextOf(remainingMs: number) {
  const days = Math.floor(remainingMs / DAY_MS);
  const sinceDay = remainingMs % DAY_MS;
  const hours = Math.floor(sinceDay / HOUR_MS);
  const sinceHour = remainingMs % HOUR_MS;
  const minutes = Math.floor(sinceHour / MINUTE_MS);
  const sinceMinute = remainingMs % MINUTE_MS;
  const seconds = Math.floor(sinceMinute / SECOND_MS);
  const time = [hours, minutes, seconds].map(twoDigits).join(':');
  return `${days}d ${time}`;
}

/**
 * The only part of the block that ticks. Until the browser has a clock the length of the offer
 * stands in, so the page and its first paint agree.
 */
export function Countdown() {
  const now = useNow(SECOND_MS);
  const hasClock = now > 0;
  let remaining = OFFER_LENGTH_MS;
  if (hasClock) {
    remaining = Math.max(0, ENDS_AT - now);
  }
  const isOver = remaining === 0;

  return (
    <p className='flex items-center gap-2 text-[13px]'>
      <span className='text-muted-foreground'>Ends in</span>
      <span
        role='timer'
        aria-label='Time left in the offer'
        className='bg-foreground/[0.06] inline-block w-28 rounded-md px-2 py-1 text-center font-medium tabular-nums'
      >
        {clockTextOf(remaining)}
      </span>
      {isOver && <span className='text-muted-foreground'>The offer ended</span>}
    </p>
  );
}

import type { SeriesSlot } from '@/registry/ndeko/lib/agent-run';

export const OFFER = {
  product: 'Lumo',
  label: 'Launch offer',
  title: 'Founding members get three perks',
  lead: 'The offer closes when the clock runs out or the spots are claimed, whichever comes first.',
};

const HOUR_MS = 3_600_000;

const MINUTE_MS = 60_000;

const SECOND_MS = 1000;

const OFFER_HOURS_MS = 54 * HOUR_MS;

const OFFER_MINUTES_MS = 41 * MINUTE_MS;

const OFFER_SECONDS_MS = 12 * SECOND_MS;

export const OFFER_LENGTH_MS =
  OFFER_HOURS_MS + OFFER_MINUTES_MS + OFFER_SECONDS_MS;

export type PerkId = 'price' | 'call' | 'credits';

export type Perk = {
  id: PerkId;
  title: string;
  detail: string;
  cap: number;
  claimedAtLoad: number;
  series: SeriesSlot;
};

export const PERKS: Perk[] = [
  {
    id: 'price',
    title: 'Founding price',
    detail: 'Keep $12 a month for as long as you stay, instead of $24',
    cap: 500,
    claimedAtLoad: 396,
    series: 1,
  },
  {
    id: 'call',
    title: 'Setup call',
    detail: 'A 30 minute call with the team to wire your first agent',
    cap: 60,
    claimedAtLoad: 34,
    series: 2,
  },
  {
    id: 'credits',
    title: 'Bonus credits',
    detail: '5,000 credits added to your first month',
    cap: 400,
    claimedAtLoad: 255,
    series: 3,
  },
];

export type Join = { id: PerkId; count: number };

export const JOINS: Join[] = [
  { id: 'price', count: 9 },
  { id: 'credits', count: 14 },
  { id: 'call', count: 2 },
  { id: 'price', count: 11 },
  { id: 'credits', count: 8 },
  { id: 'call', count: 3 },
  { id: 'price', count: 7 },
];

export const DEMO_CLAIM: PerkId = 'call';

export type Claimed = Record<PerkId, number>;

function claimedAtLoadOf() {
  const claimed: Claimed = { price: 0, call: 0, credits: 0 };
  for (const perk of PERKS) {
    claimed[perk.id] = perk.claimedAtLoad;
  }
  return claimed;
}

export const CLAIMED_AT_LOAD = claimedAtLoadOf();

export function perkOf(id: PerkId) {
  const perk = PERKS.find((candidate) => candidate.id === id);
  return perk ?? PERKS[0];
}

export function shareOf(claimed: number, cap: number) {
  if (cap <= 0) {
    return 0;
  }
  const share = claimed / cap;
  return Math.min(1, share);
}
